  createRefinedChunkMesh_fn = function(obj, size, segments, baseDepth, biome = "grass") {
    const group = new Group();
    const half = size / 2;
    const zScale = 22;
    const maxV = obj.maxVisualValue || 50;
    const gridZ = [];
    let minH = Infinity;
    for (let j = 0; j <= segments; j++) {
      gridZ[j] = [];
      const v = j / segments;
      const yNorm = obj.min + v * (obj.max - obj.min);
      for (let i = 0; i <= segments; i++) {
        const u = i / segments;
        const xNorm = obj.min + u * (obj.max - obj.min);
        const zVal = obj.evaluate(xNorm, yNorm);
        const zNorm = Math.min(1.2, Math.max(0, zVal / maxV));
        const h = zNorm * zScale;
        gridZ[j][i] = h;
        if (h < minH) minH = h;
      }
    }
    const geom = new BufferGeometry();
    const positions = [];
    const colors = [];
    const indices = [];
    const getSideColor = (y, isGrass) => {
      const c = new Color();
      if (isGrass) {
        if (y > 2) c.setHex(5913896);
        else if (y > -5) c.setHex(9069377);
        else if (y > -13) c.setHex(12427389);
        else if (y > -20) c.setHex(7425072);
        else c.setHex(3679253);
      } else {
        if (y > 2) c.setHex(8139803);
        else if (y > -5) c.setHex(10898216);
        else if (y > -13) c.setHex(13926231);
        else if (y > -20) c.setHex(9190174);
        else c.setHex(4856588);
      }
      return c;
    };
    const rowVerts = segments + 1;
    for (let j = 0; j <= segments; j++) {
      for (let i = 0; i <= segments; i++) {
        const x = -half + i / segments * size;
        const y = gridZ[j][i];
        const z = -half + j / segments * size;
        positions.push(x, y, z);
        const hNorm = gridZ[j][i] / zScale;
        const c = new Color();
        if (biome === "grass") {
          if (hNorm < 0.12) c.setHSL(0.5, 0.8, 0.55);
          else if (hNorm < 0.55) c.setHSL(0.3, 0.65, 0.36 + hNorm * 0.2);
          else c.setHSL(0.12, 0.25, 0.5 + hNorm * 0.18);
        } else {
          if (hNorm < 0.12) c.setHSL(0.11, 0.75, 0.65);
          else if (hNorm < 0.55) c.setHSL(0.06, 0.72, 0.48);
          else c.setHSL(0.02, 0.6, 0.38);
        }
        colors.push(c.r, c.g, c.b);
      }
    }
    for (let j = 0; j < segments; j++) {
      for (let i = 0; i < segments; i++) {
        const a = j * rowVerts + i;
        const b = a + 1;
        const c = (j + 1) * rowVerts + i;
        const d = c + 1;
        indices.push(a, c, b);
        indices.push(b, c, d);
      }
    }
    const addSkirt = (getTopCoords, count) => {
      const startIdx = positions.length / 3;
      for (let k = 0; k <= count; k++) {
        const top = getTopCoords(k);
        positions.push(top.x, top.y, top.z);
        const ct = getSideColor(top.y, biome === "grass");
        colors.push(ct.r, ct.g, ct.b);
        positions.push(top.x, -baseDepth, top.z);
        const cb = getSideColor(-baseDepth, biome === "grass");
        colors.push(cb.r, cb.g, cb.b);
      }
      for (let k = 0; k < count; k++) {
        const i0 = startIdx + k * 2;
        const i1 = i0 + 1;
        const i2 = i0 + 2;
        const i3 = i0 + 3;
        indices.push(i0, i1, i2);
        indices.push(i2, i1, i3);
      }
    };
    addSkirt((k) => ({ x: -half + k / segments * size, y: gridZ[0][k], z: -half }), segments);
    addSkirt((k) => ({ x: half - k / segments * size, y: gridZ[segments][segments - k], z: half }), segments);
    addSkirt((k) => ({ x: -half, y: gridZ[segments - k][0], z: half - k / segments * size }), segments);
    addSkirt((k) => ({ x: half, y: gridZ[k][segments], z: -half + k / segments * size }), segments);
    const botStart = positions.length / 3;
    positions.push(-half, -baseDepth, -half);
    positions.push(half, -baseDepth, -half);
    positions.push(half, -baseDepth, half);
    positions.push(-half, -baseDepth, half);
    const cBot = getSideColor(-baseDepth, biome === "grass");
    for (let k = 0; k < 4; k++) colors.push(cBot.r, cBot.g, cBot.b);
    indices.push(botStart, botStart + 2, botStart + 1);
    indices.push(botStart, botStart + 3, botStart + 2);
    geom.setAttribute("position", new Float32BufferAttribute(positions, 3));
    geom.setAttribute("color", new Float32BufferAttribute(colors, 3));
    geom.setIndex(indices);
    geom.computeVertexNormals();
    const topMat = new MeshStandardMaterial({
      vertexColors: true,
      roughness: 0.65,
      metalness: 0.1,
      flatShading: false,
      wireframe: this.wireframe
    });
    const chunkMesh = new Mesh(geom, topMat);
    chunkMesh.receiveShadow = true;
    chunkMesh.castShadow = true;
    group.add(chunkMesh);
    if (biome === "grass") {
      const waterGeom = new PlaneGeometry(size * 0.44, size * 0.44);
      waterGeom.rotateX(-Math.PI / 2);
      const waterMat = new MeshStandardMaterial({
        color: 3718648,
        transparent: true,
        opacity: 0.68,
        roughness: 0.08,
        metalness: 0.5
      });
      const water = new Mesh(waterGeom, waterMat);
      water.position.set(0, minH + 1.2, 0);
      group.add(water);
    }
    return group;
  };
